import type { PromptAttachment } from "@/components/Prompt";

const [files, setFiles] = React.useState<PromptAttachment[]>([{ id: "notes", name: "notes.txt" }]);
const addFiles = (selected: File[]) => setFiles((current) => [...current, ...selected.map((file, index) => ({ id: `${file.name}-${index}`, name: file.name }))]);
const removeFile = (id: string) => setFiles((current) => current.filter((file) => file.id !== id));
const send = (message: string) => {};

<Prompt onSubmit={send} onFiles={addFiles}>
  <Prompt.Attachments items={files} onRemove={removeFile} />
  <Prompt.Textarea />
  <Prompt.Toolbar>
    <Prompt.Attach />
    <Prompt.Actions>
      <Prompt.Submit />
    </Prompt.Actions>
  </Prompt.Toolbar>
</Prompt>
